CREATE   VIEW [RegsBI].[vwConnection_CE]
AS
SELECT
	[connectionid],
	[name],
	[createdon],
	[createdby],
	[CreatedByName],
	[modifiedon],
	[modifiedby],
	[modifiedbyname],
	[ownerid],
	[OwnerIdName],
	[record1id],
	[record1id_entitytype],
	[record1objecttypecode],
	[record1objecttypecode_Description],
	[record1roleid],
	[record1roleidName],
	[record2id],
	[record2id_entitytype],
	[record2objecttypecode],
	[record2objecttypecode_Description],
	[record2roleid],
	[record2roleidName],
	[ismaster],
	[transactioncurrencyid],
	[owningbusinessunit],
	[owningbusinessunitName],
	[relatedconnectionid],
	[owninguser],
	[OwningUserName],
	[createdonbehalfby],
	[CreatedOnBehalfByName],
	[modifiedonbehalfby],
	[ModifiedOnBehalfByName],
	[exchangerate],
	[description],
	[statecode],
	[StateCode_Description],
	[statuscode],
	[StatusCode_Description]
FROM [synapse_ce].[vwConnection]
